import { CheckoutPaymentIntent, Client, Environment, OrdersController, PaymentsController } from "@paypal/paypal-server-sdk";
import { paypalApiBase, paypalEnv, type PayPalEnv } from "./env";
import { PAYPAL_TIMEOUT_MS, paypalFetch, SDK_HTTP } from "./http";

/**
 * PayPal Server SDK (generated by APIMatic) and raw REST, both on the account PAYPAL_ENV names (src/lib/paypal/env.ts:
 * the sandbox unless it says "live"). Every call has a 15-second timeout and one safe retry (src/lib/paypal/http.ts).
 */
let client: Client | null = null;

export function paypalConfigured() {
  return Boolean(process.env.PAYPAL_CLIENT_ID && process.env.PAYPAL_CLIENT_SECRET);
}

/** The Server SDK's environment for PAYPAL_ENV. */
export const sdkEnvironment = (env: PayPalEnv = paypalEnv()) => (env === "live" ? Environment.Production : Environment.Sandbox);

/** The Server SDK's configuration for one app's credentials: the environment, the timeout and the retry rule. */
export function sdkConfig(clientId: string, secret: string, env: PayPalEnv = paypalEnv()) {
  return {
    clientCredentialsAuthCredentials: { oAuthClientId: clientId, oAuthClientSecret: secret },
    timeout: PAYPAL_TIMEOUT_MS,
    httpClientOptions: SDK_HTTP,
    environment: sdkEnvironment(env),
  };
}

export function paypal() {
  if (!paypalConfigured()) throw new Error("PayPal credentials are not set.");
  client ??= new Client(sdkConfig(process.env.PAYPAL_CLIENT_ID!.trim(), process.env.PAYPAL_CLIENT_SECRET!.trim()));
  return client;
}

export const orders = () => new OrdersController(paypal());
export const payments = () => new PaymentsController(paypal());
export { CheckoutPaymentIntent };

/** Raw REST access for APIs the SDK does not cover (Payouts, Transaction Search, webhook verification). */
let token: { value: string; exp: number; env: PayPalEnv } | null = null;
export async function accessToken() {
  const env = paypalEnv();
  if (token && token.env === env && token.exp > Date.now() + 5 * 60_000) return token.value;
  const res = await paypalFetch(`${paypalApiBase(env)}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: "Basic " + Buffer.from(`${process.env.PAYPAL_CLIENT_ID!.trim()}:${process.env.PAYPAL_CLIENT_SECRET!.trim()}`).toString("base64"),
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
  });
  if (!res.ok) throw new Error(`PayPal token request failed (${res.status})`);
  const j = (await res.json()) as { access_token: string; expires_in: number };
  token = { value: j.access_token, exp: Date.now() + j.expires_in * 1000, env };
  return token.value;
}

export async function paypalRest<T>(path: string, init: RequestInit & { requestId?: string } = {}): Promise<{ status: number; body: T; debugId: string | null }> {
  const t = await accessToken();
  const { requestId, headers, ...rest } = init;
  const res = await paypalFetch(`${paypalApiBase()}${path}`, {
    ...rest,
    headers: {
      Authorization: `Bearer ${t}`,
      "Content-Type": "application/json",
      ...(requestId ? { "PayPal-Request-Id": requestId } : {}),
      ...((headers as Record<string, string>) ?? {}),
    },
  });
  const body = (await res.json().catch(() => ({}))) as T;
  return { status: res.status, body, debugId: res.headers.get("paypal-debug-id") };
}
